# Exercise the actual UART decoder with a deterministic DMA/NVIC model.
from pathlib import Path
import os, shutil, subprocess
r=Path(__file__).resolve().parents[1]
out=r/'.build/rt5_uart';out.mkdir(parents=True,exist_ok=True)
s=(r/'Xe_Can_Bang/Core/Src/esp32_comm.c').read_text(encoding='utf-8')
body=s[s.index('void ESP32_Comm_Process(void)'):s.index('void ESP32_Comm_FlushRx(void)')]
pre='\n#include <stdint.h>\n#include <assert.h>\n#include <stdio.h>\n#include <string.h>\n#define ESP32_RX_BUF_SIZE 256\n#define PARSER_BUF_SIZE 128\n#define HAL_UART_ERROR_NONE 0\n#define HAL_UART_STATE_READY 0\n#define DMA_SxCR_EN 1\n#define TIM4_IRQn 4\n#define __DSB() ((void)0)\n#define __ISB() ((void)0)\n#define __DMB() ((void)0)\nstatic unsigned enabled=1,calls,now=100,counter=256,restarts;\nstatic struct {unsigned CR;} dma={1};\nstatic struct {void *unused;struct {unsigned CR;} *Instance;} rx;\nstatic struct {unsigned ErrorCode,RxState;typeof(rx) *hdmarx;} huart1;\nstatic struct {unsigned SR,DR;} usart;\n#define USART1 (&usart)\n#define __HAL_UART_CLEAR_OREFLAG(x) ((void)x)\n#define __HAL_UART_CLEAR_NEFLAG(x) ((void)x)\n#define __HAL_UART_CLEAR_FEFLAG(x) ((void)x)\n#define __HAL_UART_CLEAR_PEFLAG(x) ((void)x)\n#define __HAL_DMA_GET_COUNTER(x) (counter)\nstatic uint8_t s_rx_dma_buf[256];static unsigned s_rx_read_idx,s_packet_idx,s_in_packet;\nstatic char s_packet_buf[PARSER_BUF_SIZE];\nstatic struct {unsigned last_cmd_time;float v_target,steer_cmd;} s_command;\nunsigned HAL_GetTick(void){return now;}\nunsigned NVIC_GetEnableIRQ(int x){(void)x;return enabled;}\nvoid HAL_NVIC_DisableIRQ(int x){(void)x;enabled=0;}\nvoid HAL_NVIC_EnableIRQ(int x){(void)x;enabled=1;}\nvoid HAL_UART_Receive_DMA(void *h,void *p,unsigned n){(void)h;(void)p;(void)n;assert(enabled);restarts++;counter=256;dma.CR=1;huart1.RxState=1;}\nstatic void Parse_Packet(char *p){assert(!enabled);assert(!strcmp(p,"$PING")||!strcmp(p,"$STOP"));calls++;}\n'
post='int main(void){rx.Instance=(void*)&dma;huart1.hdmarx=&rx;huart1.RxState=1;\n const char *s="$PING*$STOP*$PING*$PING*$STOP*$PING*$PING*$PING*$STOP*$PING*$PING*$STOP*$PING*$PING*";\n unsigned n=strlen(s);memcpy(s_rx_dma_buf,s,n);counter=256-n;\n ESP32_Comm_Process();assert(s_rx_read_idx==64&&enabled&&calls>0);\n ESP32_Comm_Process();assert(s_rx_read_idx==n&&enabled&&calls==14);\n s_rx_read_idx=s_packet_idx=s_in_packet=0;calls=0;enabled=0;counter=250;\n ESP32_Comm_Process();assert(!enabled&&calls==1); // do not re-enable an intentionally disabled timer\n enabled=1;huart1.ErrorCode=1;ESP32_Comm_Process();assert(enabled&&restarts==1);\n puts("PASS actual UART process: 64-byte budget, partial packets, TIM4 publication, IRQ-state restore, DMA recovery with interrupts alive.");}\n'
p=out/'test.c';p.write_text(pre+body+post,encoding='utf-8')
cc=os.environ.get('CC') or shutil.which('gcc') or 'C:/msys64/ucrt64/bin/gcc.exe'
exe=out/'test.exe'
subprocess.run([cc,'-std=gnu11','-Wall','-Wextra','-Werror',str(p),'-o',str(exe)],check=True)
subprocess.run([str(exe)],check=True)
